import React, { useState, useEffect } from "react";

function Home() {
  const [resumeText, setResumeText] = useState("");
  const [jobDesc, setJobDesc] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  // ✅ AUTH CHECK
  useEffect(() => {
    const token = localStorage.getItem("token");

    if (!token) {
      window.location.href = "/login";
    }
  }, []);

  // =========================
  // 🔥 OPTIMIZE FUNCTION
  // =========================
  const handleOptimize = async () => {
    if (!resumeText || !jobDesc) {
      alert("Please fill all fields");
      return;
    }

    try {
      setLoading(true);

      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/optimize", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // ✅ FIXED
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
        }),
      });

      const data = await res.json();

      if (res.ok) {
        setResult(data);
      } else {
        alert(data.msg || "Optimization failed");
      }
    } catch (err) {
      console.error(err);
      alert("Server error");
    } finally {
      setLoading(false);
    }
  };

  // =========================
  // 💾 SAVE FUNCTION
  // =========================
  const handleSave = async () => {
    try {
      const token = localStorage.getItem("token");

      await fetch("http://localhost:5000/api/resume/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // ✅ FIXED
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
          score: result.score,
          optimizedText: result.optimizedText,
        }),
      });

      alert("Saved successfully");
    } catch (err) {
      console.error(err);
      alert("Save failed");
    }
  };

  return (
    <div style={styles.container}>
      <h1>CareerForge Pro 🚀</h1>

      <div style={styles.card}>
        {/* RESUME INPUT */}
        <textarea
          placeholder="Paste your Resume..."
          value={resumeText}
          onChange={(e) => setResumeText(e.target.value)}
          style={styles.textarea}
        />

        {/* JOB DESCRIPTION */}
        <textarea
          placeholder="Paste Job Description..."
          value={jobDesc}
          onChange={(e) => setJobDesc(e.target.value)}
          style={styles.textarea}
        />

        {/* BUTTON */}
        <button onClick={handleOptimize} style={styles.button}>
          {loading ? "Optimizing..." : "Optimize Resume"}
        </button>

        {/* RESULT */}
        {result && (
          <div style={styles.result}>
            <h3>ATS Score: {result.score}</h3>

            <h4>Optimized Resume:</h4>
            <p>{result.optimizedText}</p>

            {/* 🔥 SAVE BUTTON */}
            <button onClick={handleSave} style={styles.button}>
              Save Resume
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

// =========================
// 🎨 STYLES
// =========================
const styles = {
  container: {
    textAlign: "center",
    padding: "40px",
    color: "white",
  },
  card: {
    marginTop: "20px",
  },
  textarea: {
    width: "80%",
    height: "120px",
    margin: "10px",
    padding: "10px",
  },
  button: {
    marginTop: "20px",
    padding: "10px 20px",
    background: "#007bff",
    color: "white",
    border: "none",
    cursor: "pointer",
  },
  result: {
    marginTop: "20px",
    textAlign: "left",
    width: "80%",
    marginInline: "auto",
  },
};

export default Home;
